// @generated by:gauntlet run:godseye-audit-r1-r4
import { setTimeout as wait } from "node:timers/promises";
import { InfrastructureEngine, runJobScheduler } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import type { OutboxSender, OutboxSendResult } from "../packages/core/src/jobs-state.js";
import { deferred, type JobsFixture, jobsFixture, SenderFixture } from "./jobs-helpers.js";

const DISPATCH_MS = 20;
const TEST_GUARD_MS = 500;

describe("T19 bounded outbox provider calls and scheduler liveness (audit R2)", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  const engineFor = (senders: ReadonlyMap<string, OutboxSender>, dispatchTimeoutMs = DISPATCH_MS) =>
    new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      jobs: { senders, dispatchTimeoutMs },
    }).jobs;
  // The outer guard releases intentionally hung fixtures even against the broken implementation.
  async function bounded(work: Promise<unknown>, release: () => void) {
    const finished = await Promise.race([
      work.then(() => true),
      wait(TEST_GUARD_MS).then(() => false),
    ]);
    if (!finished) release();
    await work;
    expect(finished).toBe(true);
  }
  async function enqueue(engine: ReturnType<typeof engineFor>, key: string) {
    await engine.transact((tx) => engine.enqueueOutbox(tx, fixture.intent(key)));
  }

  it("bounds a hung send, preserves unknown and ignores its late acknowledgement", async () => {
    const pending = deferred<OutboxSendResult>();
    fixture.sender.behavior = () => pending.promise;
    const engine = engineFor(new Map([["fixture.sink", fixture.sender]]));
    await enqueue(engine, "audit-hung-send-001");

    await bounded(engine.tick(), () => pending.resolve({ status: "delivered" }));
    expect((await fixture.outboxRows())[0]).toMatchObject({ state: "unknown", attempts: 1 });
    await engine.tick();
    expect(fixture.sender.sends).toHaveLength(1);
    pending.resolve({ status: "delivered", evidenceRef: "late:ack" });
    await wait(DISPATCH_MS);

    expect((await fixture.outboxRows())[0]).toMatchObject({ state: "unknown", attempts: 1 });
  });

  it("bounds a hung inspection and does not accept a late delivered probe", async () => {
    const pending = deferred<"delivered" | "absent" | "unknown">();
    fixture.sender.behavior = async () => ({ status: "unknown" });
    fixture.sender.inspect = () => pending.promise;
    const engine = engineFor(new Map([["fixture.sink", fixture.sender]]));
    await enqueue(engine, "audit-hung-probe-001");
    await engine.tick();

    await bounded(engine.tick(), () => pending.resolve("delivered"));
    expect((await fixture.outboxRows())[0]?.state).toBe("reconciling");
    pending.resolve("delivered");
    await wait(DISPATCH_MS);

    expect((await fixture.outboxRows())[0]?.state).toBe("reconciling");
    expect(fixture.sender.sends).toHaveLength(1);
  });

  it("continues delivering another cell through a healthy destination after a hung sender", async () => {
    const pending = deferred<OutboxSendResult>();
    fixture.sender.behavior = () => pending.promise;
    const healthy = new SenderFixture();
    const engine = engineFor(
      new Map([
        ["fixture.sink", fixture.sender],
        ["fixture.fast", healthy],
      ]),
    );
    await enqueue(engine, "audit-slow-cell-001");
    const environment = fixture.secondProject.environments.find(
      (row) => row.kind === "development",
    );
    if (!environment) throw new Error("Second fixture cell missing");
    await engine.transact((tx) =>
      engine.enqueueOutbox(tx, {
        ...fixture.intent("audit-fast-cell-001"),
        projectId: fixture.secondProject.id,
        environmentId: environment.id,
        destination: "fixture.fast",
      }),
    );

    await bounded(engine.tick(), () => pending.resolve({ status: "delivered" }));
    expect(healthy.sends).toHaveLength(1);
    expect(
      (await fixture.outboxRows()).find((row) => row.effectKey === "audit-fast-cell-001"),
    ).toMatchObject({ state: "delivered", environmentId: environment.id });
    pending.resolve({ status: "delivered" });
  });

  it("stops the scheduler after abort even when an outbox send never acknowledges", async () => {
    const pending = deferred<OutboxSendResult>();
    const started = deferred();
    fixture.sender.behavior = () => {
      started.resolve();
      return pending.promise;
    };
    const engine = engineFor(new Map([["fixture.sink", fixture.sender]]), 10_000);
    await enqueue(engine, "audit-abort-send-001");
    const abort = new AbortController();
    const pump = runJobScheduler(engine, { signal: abort.signal, intervalMs: 5 });
    await started.promise;

    abort.abort();
    await bounded(pump, () => pending.resolve({ status: "delivered" }));
    expect((await fixture.outboxRows())[0]?.state).toBe("unknown");
    pending.resolve({ status: "delivered" });
  });

  it("never stacks more unresolved calls for an occupied cell and destination", async () => {
    const pending = deferred<OutboxSendResult>();
    fixture.sender.behavior = () => pending.promise;
    const engine = engineFor(new Map([["fixture.sink", fixture.sender]]));
    await enqueue(engine, "audit-retained-call-001");
    await bounded(engine.tick(), () => pending.resolve({ status: "delivered" }));
    await enqueue(engine, "audit-retained-call-002");

    for (let tick = 0; tick < 3; tick++) await engine.tick();

    expect(fixture.sender.sends).toHaveLength(1);
    expect(
      (await fixture.outboxRows()).find((row) => row.effectKey === "audit-retained-call-002"),
    ).toMatchObject({ state: "pending", attempts: 0 });
    pending.resolve({ status: "delivered" });
  });

  it("delivers healthy work beyond a full batch of pending intents for an occupied destination", async () => {
    const pending = deferred<OutboxSendResult>();
    fixture.sender.behavior = () => pending.promise;
    const healthy = new SenderFixture();
    const engine = engineFor(
      new Map([
        ["fixture.sink", fixture.sender],
        ["fixture.fast", healthy],
      ]),
    );
    await enqueue(engine, "audit-occupied-batch-start");
    await bounded(engine.tick(), () => pending.resolve({ status: "delivered" }));
    await engine.transact(async (tx) => {
      for (let index = 0; index < 51; index++)
        await engine.enqueueOutbox(tx, fixture.intent(`audit-occupied-batch-${index}`));
      await engine.enqueueOutbox(tx, {
        ...fixture.intent("audit-healthy-after-batch"),
        destination: "fixture.fast",
      });
    });

    await engine.tick();

    expect(healthy.sends).toHaveLength(1);
    expect(fixture.sender.sends).toHaveLength(1);
    expect(
      (await fixture.outboxRows()).find((row) => row.effectKey === "audit-healthy-after-batch"),
    ).toMatchObject({ state: "delivered", attempts: 1 });
    pending.resolve({ status: "delivered" });
  });
});
